function [Mp_init, Mp_AC_init, phi_m_init, phi_AC_init, VcClkRef, syncAligned, syncCapture] = fcn_sync_vs_vc(syncCfg)
%FCN_SYNC_VS_VC synchronizes v_s and v_c automatically (switch must be OPEN)
%   Ramps Mp (-> v_c) and Mp_AC (-> v_s) up from 0 and adjusts phi_AC until
%   both voltages reach syncCfg.Vref rms and are in phase, with phi_m = 0
%   fixed. v_c and v_s are generated by the same firmware oscillator (same
%   W0), so once aligned they stay aligned.
%
%   syncCfg: struct with the devices and the tuning (e.g. tolerance parameters).
%
%   Returns the aligned operating point, VcClkRef (v_c phasor in the
%   internal oscillator frame at no load, reference of fcn_regulate_Vc) and
%   whether the alignment tolerances were met. Plots the last capture.
%   syncCapture: that last capture (fields t, v_c, v_dac, Mp_AC, phi_AC),
%   to compare it with the v_c regulation (fcn_plot_vc_regulation).

% Auxiliary function that limits to max value (positive and negative)
clip = @(x, lim) min(max(x, -lim), lim);

ts = syncCfg.ts;
scaleVc = syncCfg.probeVoltsPerUnit(syncCfg.idxVc);
scaleVs = syncCfg.probeVoltsPerUnit(syncCfg.idxVs);

% Initializing amplitudes and phases
Mp_init = 0.0;
Mp_AC_init = 0.0;
phi_m_init = 0.0;
phi_AC_init = 0.0;

% phiSign = d(angle(vs/vc)) / d(phi_AC): +1 if increasing phi_AC moves v_s
% ahead of v_c.
phiSign = 1;
phiSignKnown = false;

% Write first commands
ts.write("Config", struct("wBlinkPeriod_s", 0.5));
ts.write("Config", struct("wphi_m", phi_m_init));
ts.write("Config", struct("wmode", 1));

syncAligned = false;
dphiPrev = NaN;     % phase error at the previous valid iteration
dPhiACPrev = 0;     % phi_AC step applied after that measurement

for k = 1:syncCfg.MaxIter

    % Sets converter/AC source operation point
    ts.write("Config", struct("wMp", Mp_init));
    ts.write("Config", struct("wMpAC", Mp_AC_init));
    ts.write("Config", struct("wphi_AC", phi_AC_init));
    pause(syncCfg.Settle_s); % Pause before doing a new voltage measurement

    % Measures v_c and v_s voltages and transform them to phasors to be able to analyse
    % its phases
    [~, ~, channelData, ~] = picoscope_acquisition(syncCfg.ps4000aDeviceObj, syncCfg.numChannels);
    Vc = fcn_FundamentalPhasor(channelData{syncCfg.idxVc} / scaleVc, syncCfg.dtScope, syncCfg.f0);
    Vs = fcn_FundamentalPhasor(channelData{syncCfg.idxVs} / scaleVs, syncCfg.dtScope, syncCfg.f0);
    VcRms = abs(Vc);
    VsRms = abs(Vs);
    phaseValid = min(VcRms, VsRms) > syncCfg.Vmin;
    dphi = angle(Vs / Vc);   % > 0 : v_s leads v_c

    fprintf('Sync %2d | Mp %.4f Mp_AC %.4f phi_AC %+.3f | Vc %5.2f Vs %5.2f V | dphi %+6.2f deg | |Vs-Vc| %.2f V\n', ...
        k, Mp_init, Mp_AC_init, phi_AC_init, VcRms, VsRms, rad2deg(dphi), abs(Vs - Vc));

    if max(VcRms, VsRms) > syncCfg.Vmax
        ts.write("Config", struct("wMp", 0.0));
        ts.write("Config", struct("wMpAC", 0.0));
        error('Sync aborted: voltage above %.1f V rms, Mp and Mp_AC set to 0.', syncCfg.Vmax);
    end

    % Verifies end criteria: if v_c and v_s voltages are aligned in
    % amplitude and phase
    if abs(VcRms - syncCfg.Vref) < syncCfg.TolV && abs(VsRms - syncCfg.Vref) < syncCfg.TolV ...
            && phaseValid && abs(dphi) < syncCfg.TolPhi
        syncAligned = true;
        break;
    end

    % Identify the sign of phi_AC from the response to the previous phase
    % step. Only trusted if the measured slope is close to +/-1 and the step is big enough.
    if ~phiSignKnown && phaseValid && ~isnan(dphiPrev) && abs(dPhiACPrev) >= 0.02
        slope = angle(exp(1j * (dphi - dphiPrev))) / dPhiACPrev;
        if abs(slope) > 0.5 && abs(slope) < 2
            phiSign = sign(slope);
            phiSignKnown = true;
            fprintf('Sync: phi_AC sign identified: %+d (slope %.2f)\n', phiSign, slope);
        end
    end

    % Amplitudes update: proportional correction using the gain V/M,
    % or a blind ramp while the voltage is too small to be measured.
    if VcRms > syncCfg.Vmin && Mp_init > 0
        dMp = syncCfg.Alpha * (syncCfg.Vref - VcRms) * Mp_init / VcRms;
    else
        dMp = syncCfg.MaxStepM;
    end
    if VsRms > syncCfg.Vmin && Mp_AC_init > 0
        dMpAC = syncCfg.Alpha * (syncCfg.Vref - VsRms) * Mp_AC_init / VsRms;
    else
        dMpAC = syncCfg.MaxStepM;
    end
    % Limits variation of modulation amplitude to MaxStepM (both
    % positive and negative values)
    Mp_init    = min(max(Mp_init    + clip(dMp,   syncCfg.MaxStepM), 0), syncCfg.Mmax);
    Mp_AC_init = min(max(Mp_AC_init + clip(dMpAC, syncCfg.MaxStepM), 0), syncCfg.Mmax);

    % Phase: only corrected once both voltages are measurable.
    if phaseValid
        % Limits variation of modulation phase to MaxStepPhi (both
        % positive and negative values)
        dPhiAC = -clip(syncCfg.Alpha * dphi / phiSign, syncCfg.MaxStepPhi);
        dphiPrev = dphi;
    else
        dPhiAC = 0;
        dphiPrev = NaN;
    end
    dPhiACPrev = dPhiAC;
    phi_AC_init = angle(exp(1j * (phi_AC_init + dPhiAC)));   % keep in (-pi, pi]

end

% Reference for the v_c regulation: phase of v_c relative to the internal
% oscillator at no load (last capture, switch open), with amplitude Vref.
% The DAC output gives the oscillator phase within the same capture.
Vdac = fcn_FundamentalPhasor(channelData{syncCfg.idxVdac} / syncCfg.probeVoltsPerUnit(syncCfg.idxVdac), syncCfg.dtScope, syncCfg.f0);
VcClkRef = syncCfg.Vref * exp(1j * angle(Vc * conj(Vdac) / abs(Vdac) * exp(1j * phi_AC_init)));

% Plot the last capture of the loop (the one that met the alignment
% criteria) to check v_c and v_s visually before closing the switch.
vcSync = channelData{syncCfg.idxVc} / scaleVc;
vsSync = channelData{syncCfg.idxVs} / scaleVs;
tSyncMs = (0:numel(vcSync) - 1) * syncCfg.dtScope * 1e3;

% Last capture, reference of the v_c regulation
syncCapture.t = (0:numel(vcSync) - 1).' * syncCfg.dtScope;
syncCapture.v_c = vcSync;
syncCapture.v_dac = channelData{syncCfg.idxVdac} / syncCfg.probeVoltsPerUnit(syncCfg.idxVdac);
syncCapture.Mp_AC = Mp_AC_init;
syncCapture.phi_AC = phi_AC_init;

fcn_reuse_figure('Alignment of v_c and v_s'); % one window, updated at each call

subplot(2, 1, 1);
plot(tSyncMs, vcSync, tSyncMs, vsSync);
grid on;
ylabel('Voltage (V)');
legend('v_c (ch D)', 'v_s (ch C)');
title(sprintf('Iteration %d | V_c = %.2f V, V_s = %.2f V rms | \\Delta\\phi = %+.2f deg', ...
    k, VcRms, VsRms, rad2deg(dphi)));

subplot(2, 1, 2);
plot(tSyncMs, vsSync - vcSync);
grid on;
xlabel('Time (ms)');
ylabel('v_s - v_c (V)');
title(sprintf('Difference | fundamental |V_s - V_c| = %.2f V rms', abs(Vs - Vc)));

drawnow;   % show the figure before the caller's input() blocks

if syncAligned
    fprintf('Sync: ALIGNED after %d iterations: Mp = %.4f, Mp_AC = %.4f, phi_AC = %.4f rad\n', ...
        k, Mp_init, Mp_AC_init, phi_AC_init);
else
    warning('Sync: NOT aligned after %d iterations - do NOT close the switch.', syncCfg.MaxIter);
end

end
